// docs@ digest — email ingest rule, transform_mode 'code'.
// Runs as a function body over `input` in the QuickJS guest engine: no Intl, no require.
// Output feeds send_email through the action's params_mapping
// (subject / html / text). Every string from the message is escaped.
const MAX_BODY = 4000;
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => (
  { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const from = input.from || {};
const email = String(from.email || '').trim();
const name = String(from.name || '').trim();
const who = (name && name.toLowerCase() !== email.toLowerCase()) ? name : (email || 'Unknown sender');
const subject = String(input.subject || '').trim();

// ── when ── firm-local (America/Detroit) WITHOUT Intl: the code engine
// (QuickJS) has no Intl, and its locale methods ignore timeZone. Same text
// as the V8 locale call this replaced (en-US, weekday/month short, day/year
// numeric, hour numeric, minute 2-digit) — e.g. "Mon, Oct 26, 2026, 3:05 PM"
// — from the US DST rules (2007+: 2nd Sun Mar to 1st Sun Nov; 1987-2006: 1st
// Sun Apr to last Sun Oct; earlier: last Sun Apr to last Sun Oct), switching
// at 2:00 local.
const detroitWhen = (t) => {
  const y = new Date(t).getUTCFullYear();
  const nthSun = (m, n) => { const f = new Date(Date.UTC(y, m, 1)).getUTCDay(); return 1 + ((7 - f) % 7) + 7 * (n - 1); };
  const lastSun = (m) => { const l = new Date(Date.UTC(y, m + 1, 0)); return l.getUTCDate() - l.getUTCDay(); };
  const on = y >= 2007 ? [Date.UTC(y, 2, nthSun(2, 2), 7), Date.UTC(y, 10, nthSun(10, 1), 6)]
    : y >= 1987 ? [Date.UTC(y, 3, nthSun(3, 1), 7), Date.UTC(y, 9, lastSun(9), 6)]
    : [Date.UTC(y, 3, lastSun(3), 7), Date.UTC(y, 9, lastSun(9), 6)];
  const l = new Date(t + (t >= on[0] && t < on[1] ? -4 : -5) * 3600000);
  const h = l.getUTCHours();
  return ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][l.getUTCDay()] + ', ' +
    ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'][l.getUTCMonth()] + ' ' +
    l.getUTCDate() + ', ' + l.getUTCFullYear() + ', ' + (h % 12 || 12) + ':' +
    String(l.getUTCMinutes()).padStart(2, '0') + ' ' + (h < 12 ? 'AM' : 'PM');
};
let when = String(input.date || '');
const d = new Date(input.date || input.received_at || '');
if (!isNaN(d.getTime())) {
  when = detroitWhen(d.getTime()) + ' ET';
}

// ── files ── (Gmail gives every attachment a Content-ID, PDFs included, so
// nothing is hidden on that basis.) The IMAP worker reports the ENCODED part
// size (base64, ~4/3 of the file); the Apps Script reports bytes.
const worker = !!input.mailbox;
const fmtSize = (n) => {
  let b = Number(n);
  if (!isFinite(b) || b <= 0) return '';
  if (worker) b = b * 0.74;
  if (b < 1024) return Math.round(b) + ' B';
  if (b < 1024 * 1024) return Math.round(b / 1024) + ' KB';
  return (b / (1024 * 1024)).toFixed(1) + ' MB';
};
const TYPES = {
  pdf: ['PDF', '#b42318', '#fdecea'],
  jpg: ['JPG', '#1d7a46', '#e7f5ec'], jpeg: ['JPG', '#1d7a46', '#e7f5ec'], png: ['PNG', '#1d7a46', '#e7f5ec'],
  heic: ['HEIC', '#1d7a46', '#e7f5ec'], gif: ['GIF', '#1d7a46', '#e7f5ec'], tif: ['TIFF', '#1d7a46', '#e7f5ec'],
  tiff: ['TIFF', '#1d7a46', '#e7f5ec'], webp: ['WEBP', '#1d7a46', '#e7f5ec'],
  doc: ['DOC', '#1849a9', '#e8eefb'], docx: ['DOCX', '#1849a9', '#e8eefb'], rtf: ['RTF', '#1849a9', '#e8eefb'],
  txt: ['TXT', '#1849a9', '#e8eefb'], xls: ['XLS', '#0e6245', '#e5f4ee'], xlsx: ['XLSX', '#0e6245', '#e5f4ee'],
  csv: ['CSV', '#0e6245', '#e5f4ee'], zip: ['ZIP', '#6b4e16', '#f6efe1'],
};
const typeOf = (a) => {
  const fn = String(a.filename || '');
  const ext = (fn.match(/\.([A-Za-z0-9]{1,5})$/) || [])[1];
  const key = String(ext || '').toLowerCase();
  if (TYPES[key]) return TYPES[key];
  const sub = String(a.mime || '').toLowerCase().split('/')[1] || '';
  if (TYPES[sub]) return TYPES[sub];
  if (/^image\//i.test(a.mime || '')) return ['IMG', '#1d7a46', '#e7f5ec'];
  return ['FILE', '#475467', '#eef0f3'];
};
const files = (Array.isArray(input.attachments) ? input.attachments : []).filter(a => a && a.filename);
const nFiles = files.length;

// ── message ── quoted history trimmed, length capped
let body = String(input.text || '').replace(/\r\n?/g, '\n').replace(/[ \t]+$/gm, '');
let trimmed = false;
const quoteAt = [
  /^\s*On .{4,200}\bwrote:\s*$/m,
  /^-{2,}\s*Original Message\s*-{2,}/im,
  /^From: .+\n(?:Sent|Date): /m,
  /^_{10,}\s*$/m,
].map(re => { const m = re.exec(body); return m ? m.index : -1; }).filter(i => i > 0);
if (quoteAt.length) { body = body.slice(0, Math.min.apply(null, quoteAt)); trimmed = true; }
body = body.replace(/\n{3,}/g, '\n\n').trim();
let cut = 0;
if (body.length > MAX_BODY) { cut = body.length - MAX_BODY; body = body.slice(0, MAX_BODY).replace(/\s+\S*$/, ''); }

// ── a case id the client typed ("- Case PVXC1RMM"): 8-char Crockford
// base32, uppercase. The ?files= link fails safe on an id that isn't one.
const caseM = (subject + '\n' + body).match(/\bcase[\s:#-]+([0-9A-HJKMNP-TV-Z]{8})\b/i);
const caseId = caseM && /^[0-9A-HJKMNP-TV-Z]{8}$/.test(caseM[1]) ? caseM[1] : null;
const caseUrl = caseId ? 'https://app.4lsg.com/?files=c' + caseId + '&open=file:0' : null;

// ── subject line ── keeps the old digest's wording (filters on it still match)
const oneLine = (v) => String(v).replace(/\s+/g, ' ').trim().slice(0, 120);
const outSubject = 'New email to Docs@4LSG.com — ' + oneLine(who) +
  (nFiles ? ' (' + nFiles + (nFiles === 1 ? ' file)' : ' files)') : ' (no files)');

// ── HTML (tables + inline styles: Outlook / webmail safe) ──
const F = "font-family:'Segoe UI',Helvetica,Arial,sans-serif;";
const reply = 'mailto:' + email + '?subject=' + encodeURIComponent('Re: ' + subject);
const fileRows = files.map(a => {
  const t = typeOf(a);
  return '<tr>' +
    '<td width="52" style="padding:7px 0;vertical-align:middle;">' +
      '<span style="display:inline-block;min-width:38px;text-align:center;' + F + 'font-size:10px;font-weight:700;' +
      'letter-spacing:.04em;color:' + t[1] + ';background:' + t[2] + ';border-radius:4px;padding:3px 5px;">' + t[0] + '</span></td>' +
    '<td style="padding:7px 8px 7px 0;' + F + 'font-size:14px;color:#1d2433;word-break:break-all;">' + esc(a.filename) + '</td>' +
    '<td align="right" style="padding:7px 0;' + F + 'font-size:12px;color:#6b7385;white-space:nowrap;">' + esc(fmtSize(a.size)) + '</td>' +
    '</tr>';
}).join('<tr><td colspan="3" style="border-top:1px solid #eef0f4;font-size:0;line-height:0;">&nbsp;</td></tr>');
const bodyHtml = body
  ? esc(body).replace(/\n/g, '<br>')
  : '<span style="color:#8a92a3;font-style:italic;">' + (nFiles ? 'No message — attachments only.' : '(empty message)') + '</span>';
const label = (t) => '<div style="' + F + 'font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#6b7385;margin:0 0 8px;">' + t + '</div>';

const html =
'<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>' +
'<body style="margin:0;padding:0;background:#f2f4f7;">' +
'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f2f4f7;"><tr><td align="center" style="padding:24px 12px;">' +
'<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px;background:#ffffff;border:1px solid #dde2ea;border-radius:10px;">' +
// header
'<tr><td style="background:#1f3a5f;border-radius:10px 10px 0 0;padding:18px 24px;">' +
  '<div style="' + F + 'font-size:11px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:#b9c7dc;">docs@4lsg.com</div>' +
  '<div style="' + F + 'font-size:20px;font-weight:600;color:#ffffff;margin-top:4px;">' +
    (nFiles ? nFiles + (nFiles === 1 ? ' new document' : ' new documents') : 'New email (no attachments)') + '</div>' +
'</td></tr>' +
// sender
'<tr><td style="padding:20px 24px 4px;">' +
  label('From') +
  '<div style="' + F + 'font-size:16px;font-weight:600;color:#1d2433;">' + esc(who) + '</div>' +
  (email && who !== email ? '<div style="' + F + 'font-size:13px;color:#475467;margin-top:2px;">' + esc(email) + '</div>' : '') +
  '<div style="' + F + 'font-size:12px;color:#8a92a3;margin-top:4px;">' + esc(when) + '</div>' +
'</td></tr>' +
// subject
'<tr><td style="padding:16px 24px 4px;">' + label('Subject') +
  '<div style="' + F + 'font-size:15px;color:#1d2433;">' + (subject ? esc(subject) : '<span style="color:#8a92a3;font-style:italic;">(no subject)</span>') + '</div>' +
'</td></tr>' +
// case
(caseUrl ? '<tr><td style="padding:14px 24px 0;">' +
  '<a href="' + esc(caseUrl) + '" style="display:inline-block;' + F + 'font-size:13px;font-weight:600;color:#1f3a5f;background:#e8eefb;border:1px solid #c9d6ef;border-radius:6px;padding:7px 12px;text-decoration:none;">Open case ' + esc(caseId) + ' in YisraCase &rarr;</a>' +
  '<div style="' + F + 'font-size:11px;color:#8a92a3;margin-top:4px;">The client typed this case number; check it matches.</div>' +
'</td></tr>' : '') +
// files
'<tr><td style="padding:18px 24px 4px;">' + label('Attachments (' + nFiles + ')') +
  (nFiles
    ? '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">' + fileRows + '</table>'
    : '<div style="' + F + 'font-size:14px;color:#8a92a3;font-style:italic;">None</div>') +
'</td></tr>' +
// message
'<tr><td style="padding:18px 24px 22px;">' + label('Message') +
  '<div style="' + F + 'font-size:14px;line-height:1.5;color:#1d2433;background:#f8f9fb;border:1px solid #eef0f4;border-radius:8px;padding:12px 14px;">' + bodyHtml +
    (trimmed ? '<div style="font-size:12px;color:#8a92a3;margin-top:10px;">— earlier messages in the thread trimmed —</div>' : '') +
    (cut ? '<div style="font-size:12px;color:#8a92a3;margin-top:10px;">— message shortened (' + cut + ' more characters) —</div>' : '') +
  '</div>' +
'</td></tr>' +
// actions + footer
(email ? '<tr><td style="padding:0 24px 22px;"><a href="' + esc(reply) + '" style="display:inline-block;' + F + 'font-size:13px;font-weight:600;color:#ffffff;background:#1f3a5f;border-radius:6px;padding:9px 14px;text-decoration:none;">Reply to ' + esc(name || email) + '</a></td></tr>' : '') +
'<tr><td style="background:#f8f9fb;border-top:1px solid #eef0f4;border-radius:0 0 10px 10px;padding:12px 24px;">' +
  '<div style="' + F + 'font-size:11px;line-height:1.5;color:#8a92a3;">The original message and its files are in the stuart@4lsg.com mailbox (YisraCase &rarr; Comms). Sent automatically by YisraCase for mail to docs@4lsg.com.</div>' +
'</td></tr>' +
'</table></td></tr></table></body></html>';

// ── plain-text alternative ──
const text = [
  (nFiles ? nFiles + (nFiles === 1 ? ' new document' : ' new documents') : 'New email (no attachments)') + ' at docs@4lsg.com',
  '',
  'From: ' + who + (email && who !== email ? ' <' + email + '>' : ''),
  'Received: ' + when,
  'Subject: ' + (subject || '(no subject)'),
  caseUrl ? 'Case (as typed by the client): ' + caseId + ' — ' + caseUrl : null,
  '',
  'Attachments (' + nFiles + '):',
  nFiles ? files.map(a => '  - ' + a.filename + (fmtSize(a.size) ? ' (' + fmtSize(a.size) + ')' : '')).join('\n') : '  none',
  '',
  'Message:',
  body || (nFiles ? '(no message — attachments only)' : '(empty message)'),
  trimmed ? '\n— earlier messages in the thread trimmed —' : null,
  cut ? '— message shortened (' + cut + ' more characters) —' : null,
  '',
  '— The original message and its files are in the stuart@4lsg.com mailbox (YisraCase → Comms).',
].filter(x => x !== null).join('\n');

return { subject: outSubject, html, text, sender_email: email, files: nFiles, case_id: caseId };
